import {scopeMarkup} from './card-markup.js';
import {fineSword,bladeMachine} from './finishing-art.js';
import {bladeResponse,bladeCurve} from './finishing-model.js';
import {bindWorkbenchDrag,bindLoadGrip} from './finishing-input.js';
export const bladeCases={pig:{name:'生鐵',carbon:'3.5%',result:'脆裂',detail:'含碳較多；本例刀身在設定負荷下裂開。較硬不代表能承受彎折。'},steel:{name:'鋼鐵',carbon:'0.8%',result:'回彈',detail:'經適當熱處理的鋼刀在本例負荷下回彈，兼顧硬度與韌性。'},wrought:{name:'熟鐵',carbon:'0.01%',result:'留下彎曲',detail:'含碳很低的熟鐵較柔軟；本例卸載後留下永久彎曲，刀刃較容易變形。'}};
export function bladeIcon(){return fineSword();}
export function mountBlade(root,c,{s,record,notice,has,onCleanup}){
 let key=null,phase='empty',frame=0,alive=true,liveBend=0;const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;
 root.innerHTML=scopeMarkup(`<button class="studio-enter" data-finish-enter>進入刀材試驗台，抓一把刀開始 ↘</button><section class="finish-studio blade-studio" tabindex="-1" aria-label="刀材試驗台"><header class="finish-top"><div><small>06 / 材料工坊</small><b>不同含碳量的鐵所打造的刀，哪一把才撐得住？</b></div><span>同形狀 · 相同示意負荷</span></header><div class="finish-rack">${Object.entries(bladeCases).map(([k,d],i)=>`<div class="finish-sample" data-blade-sample="${k}" aria-label="${d.name}刀材"><div><b>${i+1} ${d.name}</b><span>${d.carbon} 碳</span></div>${scopeMarkup(fineSword(),'rack-'+k)}<small data-blade-tag="${k}">${has(k)?'✓ 已比較；可再試':'抓起刀身，放上支點 ↓'}</small></div>`).join('')}</div><div class="finish-machine">${scopeMarkup(bladeMachine(),'machine')}<div class="finish-blade-target" data-blade-target><span>刀身放這裡</span></div><div class="finish-load-grip" data-load-grip aria-label="施力把手；向下拉至標線再放開，鍵盤用上下鍵或 End 後 Enter 鬆開" aria-disabled="true"><i></i><b>↓ 拉下</b></div><div class="finish-readout"><small data-blade-name>先取一把刀</small><strong data-blade-carbon>—</strong><span>含碳量</span></div><div class="finish-live-step" data-blade-step>① 拖上刀材　→　② 拉到標線　→　③ 鬆開看結果</div></div><div class="finish-result" aria-live="polite"><b data-blade-title>先試生鐵，再比較鋼鐵與熟鐵。</b><p data-blade-description>三把外形相同；從上架直接抓一把，放到兩個支點之間。</p></div><div class="finish-results-grid">${Object.entries(bladeCases).map(([k,d])=>`<div data-result-card="${k}" class="finish-record ${has(k)?'recorded':''}"><b>${d.name} <small>${d.carbon} C</small></b><svg viewBox="0 0 210 45" aria-hidden="true"><path class="result-baseline" d="M15 18H195"/><path data-result-line d="${has(k)?resultPath(k):'M15 18H195'}"/></svg><span data-blade-record="${k}">${has(k)?d.result:'等待試驗'}</span></div>`).join('')}</div></section>`,'finish-blade');
 const q=sel=>root.querySelector(sel),board=q('.finish-machine'),grip=q('[data-load-grip]');
 const setText=(sel,text)=>q(sel).textContent=text;
 function shape(bend,broken=false){liveBend=bend;const paths=bladeCurve(bend);q('[data-flex-blade]').setAttribute('d',paths.edge);q('[data-flex-ridge]').setAttribute('d',paths.ridge);q('[data-flex-grain]').setAttribute('d',paths.ridge);q('[data-blade-whole]').toggleAttribute('hidden',broken);q('[data-broken-blade]').toggleAttribute('hidden',!broken);}
 function mount(k){cancelAnimationFrame(frame);key=k;s.selected=k;phase='mounted';shape(0);q('[data-mounted-blade]').removeAttribute('hidden');q('[data-blade-target]').classList.add('loaded');grip.setAttribute('aria-disabled','false');grip.style.transform='';q('[data-press-head]').setAttribute('transform','translate(0 0)');setText('[data-blade-carbon]',bladeCases[k].carbon);setText('[data-blade-name]',bladeCases[k].name);setText('[data-blade-title]',bladeCases[k].name+'刀已就位');setText('[data-blade-description]','抓住右側金屬把手往下拉，到金色標線後鬆開。');setText('[data-blade-step]','② 向下拉右側把手；看刀身怎麼變');root.querySelectorAll('[data-blade-sample]').forEach(e=>e.classList.toggle('selected',e.dataset.bladeSample===k));notice('刀已架好。拉到金色標線，鬆手後觀察。');}
 for(const item of root.querySelectorAll('[data-blade-sample]'))onCleanup(bindWorkbenchDrag(item,{targets:()=>[q('[data-blade-target]')],onDrop:()=>mount(item.dataset.bladeSample),onMiss:()=>notice('把刀身拖到試驗機中央的兩個支點之間。')}));
 onCleanup(bindLoadGrip(grip,board,{travelFraction:.3182,enabled:()=>phase==='mounted',onMove:value=>{if(phase!=='mounted')return;const response=bladeResponse(key,value);shape(response.bend);q('[data-press-head]').setAttribute('transform',`translate(0 ${response.bend})`);setText('[data-blade-step]',value>=.85?'③ 已到標線，鬆開看看刀身':'② 繼續拉到金色標線，再鬆開');},onRelease:value=>{
 const response=bladeResponse(key,value,true);if(!response.complete){shape(0);q('[data-press-head]').setAttribute('transform','translate(0 0)');setText('[data-blade-step]','未到標線；再拉一次，才能公平比較');notice('這次還沒到比較負荷。再拉到金色標線後鬆開。');return;}
 phase='unloading';grip.setAttribute('aria-disabled','true');const current=key,start=performance.now(),from=liveBend,duration=reduced?0:850;setText('[data-blade-step]','③ 已鬆手，觀察卸載後的刀身');
 const animate=t=>{if(!alive||current!==key)return;const p=duration?Math.min(1,(t-start)/duration):1,ease=1-Math.pow(1-p,3),bend=from+(response.bend-from)*ease;shape(bend,response.broken);q('[data-press-head]').setAttribute('transform',`translate(0 ${from*(1-ease)})`);if(p<1){frame=requestAnimationFrame(animate);return;}phase='done';record(current);const d=bladeCases[current];setText('[data-blade-title]',d.name+'刀 · '+d.result);setText('[data-blade-description]',d.detail);setText('[data-blade-step]','直接從上架取另一把刀，接著比較 ↑');setText(`[data-blade-tag="${current}"]`,'✓ 已比較；可再試');setText(`[data-blade-record="${current}"]`,d.result);const row=q(`[data-result-card="${current}"]`);row.classList.add('recorded');row.querySelector('[data-result-line]').setAttribute('d',resultPath(current));notice(d.detail);};frame=requestAnimationFrame(animate);
 }}));
 q('[data-finish-enter]').addEventListener('click',()=>{q('.finish-studio').scrollIntoView({block:'start',behavior:'instant'});q('.finish-studio').focus({preventScroll:true});});
 onCleanup(()=>{alive=false;cancelAnimationFrame(frame);});
}
function resultPath(key){return key==='pig'?'M15 18L99 25 M112 25L195 18':key==='wrought'?'M15 18Q105 59 195 18':'M15 18H195';}
